-- 080_redeem_sweep_zero_return_pnl_backfill_20260630.sql
--
-- Scoped accounting backfill for 40 closed, zero-return positions whose loss was
-- never recorded. RedeemSweep.closeLocalPositions() historically zeroed inventory
-- lots + position size WITHOUT writing settlement_ledger or updating realized_pnl
-- (the bug fixed in apps/runtime/src/modules/redeem-sweep/redeem-sweep-module.ts).
-- The 40 rows are the precise, on-chain-verified zero-return set from the
-- 2026-06-30 read-only audit (research_plankton/closed_zero_return_pnl_audit_2026-06-30.md
-- + closed_zero_return_pnl_affected_2026-06-30.csv): every one has buy cost > $0.01,
-- zero sell/settlement return, zero pnl_ledger + settlement_ledger P&L, no sell fills,
-- and fully-settled lots. Total invested $103.786735; corrected economic P&L
-- -$103.786735 (settlement_price 0, delta = -cost_basis per row).
--
-- This is data-only and intentionally disjoint from 079 (two unrelated UNKNOWN_ACCT
-- legacy rows) — no position/condition overlap. Do NOT expand or edit 079.
--
-- FK safety: settlement_ledger.condition_id REFERENCES market_resolutions(condition_id),
-- and 37/40 affected conditions have no market_resolutions row. For those, a backfill
-- marker resolution row (source 'redeem-sweep-backfill') is inserted first so the
-- settlement row satisfies the FK. The 3 conditions that already carry a
-- gamma-delisted detection row are reused untouched.
--
-- Idempotent: the allow-list is exact (position_id, token_id, condition_id), and every
-- write is guarded by the zero-return predicates plus NOT EXISTS, so re-running is a
-- no-op (realized_pnl is no longer 0; the settlement/marker rows already exist).
--
-- ROLLBACK (manual, if this scoped backfill ever needs to be undone):
--   UPDATE positions SET realized_pnl = 0
--    WHERE position_id IN (SELECT position_id FROM settlement_ledger
--                          WHERE settlement_id LIKE 'redeem-sweep-backfill-080-%');
--   DELETE FROM settlement_ledger WHERE settlement_id LIKE 'redeem-sweep-backfill-080-%';
--   DELETE FROM market_resolutions WHERE source = 'redeem-sweep-backfill';

-- Exact, verified affected rows (position_id, token_id, condition_id, invested_usd).
DROP TABLE IF EXISTS _redeem_sweep_backfill_080;
CREATE TEMP TABLE _redeem_sweep_backfill_080 (
  position_id  TEXT PRIMARY KEY,
  token_id     TEXT NOT NULL,
  condition_id TEXT NOT NULL,
  invested_usd REAL NOT NULL
);
