-- Step 1: FK parent. Insert a backfill resolution marker for affected conditions
-- that have no market_resolutions row. raw_response is omitted (nullable → NULL).
INSERT INTO market_resolutions (condition_id, resolution, resolved_at, detected_at, source, status)
SELECT a.condition_id, 'redeem-sweep-zero-return', p.closed_at, p.closed_at, 'redeem-sweep-backfill', 'settled'
FROM _redeem_sweep_backfill_080 a
JOIN positions p ON p.position_id = a.position_id
WHERE p.token_id = a.token_id
  AND p.condition_id = a.condition_id
  AND p.status = 'closed'
  AND abs(p.size) < 0.000001
  AND abs(p.realized_pnl) < 0.000001
  AND p.cost_basis_usdc > 0.01
  AND abs(p.cost_basis_usdc - a.invested_usd) < 0.00001
  AND p.closed_at IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM pnl_ledger pl WHERE pl.position_id = a.position_id)
  AND NOT EXISTS (SELECT 1 FROM settlement_ledger sl WHERE sl.position_id = a.position_id)
  AND COALESCE(
        (SELECT SUM(il.remaining_size) FROM inventory_lots il WHERE il.position_id = a.position_id),
        0
      ) < 0.000001
  AND NOT EXISTS (SELECT 1 FROM market_resolutions mr WHERE mr.condition_id = a.condition_id);

-- Step 2: settlement_ledger losing row. settlement_price 0, returned 0,
-- delta = -invested (the missing economic loss). size = original bought shares.
INSERT INTO settlement_ledger (
  settlement_id, condition_id, position_id, token_id,
  resolution, settlement_price, size, delta, settled_at
)
SELECT
  'redeem-sweep-backfill-080-' || a.token_id,
  a.condition_id,
  a.position_id,
  a.token_id,
  'redeem-sweep-zero-return',
  0.0,
  COALESCE(
    (SELECT SUM(il.size) FROM inventory_lots il
      WHERE il.position_id = a.position_id AND il.token_id = a.token_id),
    0
  ),
  -a.invested_usd,
  p.closed_at
FROM _redeem_sweep_backfill_080 a
JOIN positions p ON p.position_id = a.position_id
WHERE p.token_id = a.token_id
  AND p.condition_id = a.condition_id
  AND p.status = 'closed'
  AND abs(p.size) < 0.000001
  AND abs(p.realized_pnl) < 0.000001
  AND p.cost_basis_usdc > 0.01
  AND abs(p.cost_basis_usdc - a.invested_usd) < 0.00001
  AND p.closed_at IS NOT NULL
  AND EXISTS (
    SELECT 1 FROM inventory_lots il
     WHERE il.position_id = a.position_id AND il.token_id = a.token_id
  )
  AND COALESCE(
        (SELECT SUM(il.remaining_size) FROM inventory_lots il WHERE il.position_id = a.position_id),
        0
      ) < 0.000001
  AND NOT EXISTS (SELECT 1 FROM pnl_ledger pl WHERE pl.position_id = a.position_id)
  AND NOT EXISTS (SELECT 1 FROM settlement_ledger sl WHERE sl.position_id = a.position_id);

-- Step 3: mirror the loss into positions.realized_pnl so headline SUM(realized_pnl)
-- and the position-cycles ledger-vs-position reconciliation agree (no UNKNOWN_ACCT).
-- Guarded on realized_pnl still 0 + the freshly-inserted settlement row.
UPDATE positions
SET realized_pnl = -(
      SELECT a.invested_usd FROM _redeem_sweep_backfill_080 a
       WHERE a.position_id = positions.position_id
    )
WHERE position_id IN (SELECT position_id FROM _redeem_sweep_backfill_080)
  AND status = 'closed'
  AND abs(size) < 0.000001
  AND abs(realized_pnl) < 0.000001
  AND cost_basis_usdc > 0.01
  AND EXISTS (
    SELECT 1 FROM settlement_ledger sl
     WHERE sl.settlement_id = 'redeem-sweep-backfill-080-' || positions.token_id
       AND sl.position_id = positions.position_id
  );

DROP TABLE IF EXISTS _redeem_sweep_backfill_080;
